+					emitOptionLookup := func(varName, option string) {
+						la := generator.Args{"field": targs["field"], "fmt": targs["fmt"], "opt": strconv.Quote(option)}
+						sw.Do("  "+varName+", defined := op.HasOption($.opt$)\n", la)
